// План specs/job-payments.md 4.1 / 4.2 (#5315ab). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Только чтение (@prod-safe).
// Работа TTP lockout = JOB-0003 (переплата: оплачено больше суммы работы — решение context.md 08.11: не баг).
// 4.1 — в заголовке страницы работы номер JOB-0003, пустого «#» нет.
// 4.2 — метка вкладки Payments «Remaining to pay: $0.00» с первого показа (перезагрузка ×3), внутри вкладки строка Overpaid;
//       пока данные грузятся — полоса загрузки, а не «$0.00» → «$120.00» (реджект 12.11: сначала $0.00, потом реальная сумма).
// Факты 17.11: desktop 13 загрузок без $0.00 (до реальной суммы), android 6/6; JOB: Remaining $0.00, Paid 147, Overpaid 23.
// Не сверено с сайтом при записи: адрес работы берём из списка Jobs (клик по JOB-0003), подпись метки на вкладке.
import { test, expect } from '../../fixtures';
import { ROLE, pp } from './payments-helpers';

const JOB = 'JOB-0003';

async function openJob(page: import('@playwright/test').Page): Promise<string> {
  await page.addInitScript(() => { try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ } });
  await page.goto(pp('/jobs'));
  await page.getByText(JOB, { exact: true }).filter({ visible: true }).first().click();
  await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
  return page.url();
}

test.describe('Job page — number in the header and Remaining to pay (#5315ab)', () => {
  test('Job header shows JOB-0003 and no empty "#" #5315ab @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openJob(page);
    await expect(page.getByText(JOB).filter({ visible: true }).first()).toBeVisible({ timeout: 30_000 });
    // «Job» + пустой «#» (как было) — не должно быть строки, состоящей только из «#»
    await expect(page.getByText('#', { exact: true }).filter({ visible: true })).toHaveCount(0);
  });

  test('Overpaid job: Payments tab label shows "Remaining to pay: $0.00" from the first paint on every load, Overpaid inside #5315ab @prod-safe', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(ROLE);
    const url = await openJob(page);

    // Записываем все значения «Remaining to pay: $X» на метке вкладки с момента загрузки
    await page.addInitScript(() => {
      const seen: string[] = [];
      (window as unknown as { __qaRem: string[] }).__qaRem = seen;
      const scan = () => {
        const m = document.body?.innerText.match(/Remaining to pay:?\s*(-?\$[\d,]+(?:\.\d\d)?)/);
        if (m && seen[seen.length - 1] !== m[1]) seen.push(m[1]);
      };
      new MutationObserver(scan).observe(document, { childList: true, subtree: true, characterData: true });
    });

    for (let i = 0; i < 3; i++) {
      await page.goto(url);
      await expect(page.getByText(/Remaining to pay:?\s*\$0\.00/).first()).toBeVisible({ timeout: 30_000 });
      const seen = await page.evaluate(() => (window as unknown as { __qaRem: string[] }).__qaRem);
      expect(seen, `загрузка ${i + 1}: метка не показывала промежуточных значений`).toEqual(['$0.00']);
    }

    await page.getByRole('tab', { name: /^Payments/ }).click();
    await expect(page.getByText(/Overpaid/).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText('$-', { exact: false }), 'отрицательной суммы вида «$-27.00» нет').toHaveCount(0);
  });
});
